import { AsyncLocalStorage } from "node:async_hooks";

export interface RequestContext {
  requestId: string;
  signal: AbortSignal;
  /** Document nonce supplied by Express, rather than generated by the renderer. */
  nonce?: string;
  user?: { id: string };
  headers: Headers;
  services?: Record<string, unknown>;
}

const storage = new AsyncLocalStorage<RequestContext>();

/** Read the current RSC request; access outside a request is an application error. */
export function getRequestContext(): RequestContext {
  const context = storage.getStore();

  if (!context) {
    throw new Error("Request context is only available during an RSC request");
  }

  return context;
}

/**
 * Establish request isolation inside the RSC environment, including asynchronous
 * rendering.
 */
export function withRequestContext<T>(
  context: RequestContext,
  callback: () => T,
): T {
  return storage.run(context, callback);
}
